# tenant_pool("acme") is tenant_pool("acme")

_registry: dict[str, Pool] = {}
_lock = threading.Lock()

def tenant_pool(tenant: str) -> Pool:
    with _lock:                      # find-or-create is the critical section
        pool = _registry.get(tenant)
        if pool is None:
            _registry[tenant] = pool = Pool(tenant)
        return pool
